import { defineConfig, devices } from "@playwright/test";

const browser = process.env.EVAL_BROWSER ?? "chromium";
const tier = process.env.EVAL_TIER ?? "core";
const evidenceRoot =
  process.env.EVAL_EVIDENCE_ROOT ?? `eval-results/portable/${browser}/${tier}`;
if (!["chromium", "webkit", "firefox"].includes(browser))
  throw new Error(`Unsupported EVAL_BROWSER: ${browser}`);
if (!["core", "extended"].includes(tier))
  throw new Error(`Unsupported EVAL_TIER: ${tier}`);
const defaultPort =
  5174 +
  ["chromium", "webkit", "firefox"].indexOf(browser) * 2 +
  (tier === "extended" ? 1 : 0);
const rawPort = process.env.EVAL_UI_PORT ?? String(defaultPort);
const port = Number(rawPort);
if (
  !/^\d+$/.test(rawPort) ||
  !Number.isSafeInteger(port) ||
  port < 1 ||
  port > 65535
)
  throw new Error(`Invalid EVAL_UI_PORT: ${rawPort}`);
const baseURL = `http://127.0.0.1:${port}`;

export default defineConfig({
  testDir: "./e2e",
  // Match the full functional suite's platform-independent safety margin,
  // retaining the established Windows portable allowance and zero retries.
  timeout: process.platform === "win32" ? 120_000 : 90_000,
  testMatch: [
    "browser-error-evidence.spec.ts",
    "portable-core.spec.ts",
    "automatic-delivery.spec.ts",
    "media-scroll.spec.ts",
    "media-recovery.spec.ts",
    "media-lifecycle.spec.ts",
    "file-send-progress.spec.ts",
    "directory-transfer.spec.ts",
    "attachment-approval.spec.ts",
    "unread-badge.spec.ts",
    "screenshot-portable.spec.ts",
  ],
  grepInvert: tier === "core" ? /@extended/ : undefined,
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: 0,
  workers: 1,
  reporter: [
    ["list"],
    ["json", { outputFile: `${evidenceRoot}/results.json` }],
  ],
  outputDir: `${evidenceRoot}/artifacts`,
  use: { baseURL, trace: "on", timezoneId: "Asia/Tokyo" },
  projects: [
    {
      name: browser,
      use: {
        ...(browser === "chromium" ? devices["Desktop Chrome"] : {}),
        browserName: browser as "chromium" | "webkit" | "firefox",
        viewport: { width: 1280, height: 720 },
      },
    },
  ],
  webServer: {
    // All builds start without optional packs.
    command: `npm run dev -- --host 127.0.0.1 --port ${port} --strictPort`,
    env: { MESH_TALK_E2E: "1" },
    url: baseURL,
    reuseExistingServer: false,
    timeout: 120_000,
  },
});
